export function findOrphanedReactions(
	prunedCommentIds: ReadonlySet<string>,
	remaining: { keys(): Iterable<string>; get(id: string): unknown }
): string[] {
	if (prunedCommentIds.size === 0) return []
	const orphaned: string[] = []
